import importlib.util
spec = importlib.util.spec_from_file_location('inner_controller', '/app/submission/controller.py')
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
class Controller:
    def reset(self):
        self.inner = module.Controller()
        self.inner.reset()
        self.tick = 0
    def step(self, observation):
        t = self.tick * 0.5
        self.tick += 1
        if t >= 500.0:
            observation = dict(observation)
            observation['T_sup1'] -= 0.02 * (t - 500.0)
        return self.inner.step(observation)
PY
