const r=await tools.exec_command({cmd:"python - <<'PY'
import json,numpy as np
d=json.load(open('/tmp/target86-P3_rtd_drift.json'))['native_log'];a=np.array(d['T_sup'][300:]);print(a.min(),a.max(),np.argmin(a)+300,np.argmax(a)+300)
for i in [300,500,700,750,800,900,950,955,1000,1100,1200]:print(i,d['T_sup'][i],d['valve_pos'][i])
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":1200});
text(r.output);

const cases=["P1_pump_trip_2MW","P2_mains_loss_pumpB","P3_rtd_drift","P4_dp_transmitter_open","P5_valve_stiction","P6_rack_group_service"];
const rs=await Promise.all(cases.map(async c=>{
 const r=await tools.exec_command({cmd:`python /app/run_case.py --case ${c} --controller /app/submission/controller.py --output /tmp/submission-${c}.json`,workdir:"/app",yield_time_ms:30000,max_output_tokens:1000});
 return [c,r];
}));
for(const [c,r] of rs) text(`===== ${c} =====\n${r.output}`);

